// 🪬 Bit Sigil
// You want your sigil stamped into x's 32 bits (two's complement). The sigil reads from bit 31
// (the sign) down to bit 0: a 1 or 0 says what that bit should be, a dot means you don't care.
// Count the bits that match.
const SIGIL = ".10.10.10.10.10.10.10.10.10.10..";

function utility(x) {
  let hits = 0;
  for (let bit = 0; bit < 32; bit++) {
    const want = SIGIL[31 - bit];
    if (want !== "." && ((x >> bit) & 1) === Number(want)) hits += 1;
  }
  return hits;
}
